{
  "household_context": "A quiet Saturday unfolds as the roommates maintain their established rhythms, with late-night work bleeding into morning coffee, early morning stillness giving way to kitchen tidiness, and daylight hours surrendered to an inverted sleep schedule.",
  "occupants": [
    {
      "name": "Alex",
      "scenario": "Alex drags himself to the kitchen at 8 AM, immediately brewing a strong cup of black coffee while his work laptop remains open on the dining table from last night’s coding session. He spends the quiet morning tweaking a personal project on the couch, the steady tap of his keyboard filling the apartment."
    },
    {
      "name": "Jordan",
      "scenario": "Jordan rises before dawn to stretch on the living room rug, extending his sunrise meditation with a longer breathing sequence before the sun breaks over the horizon. After preparing a nourishing breakfast, he meticulously wipes down the counters and arranges the spice jars, all while his phone plays an audiobook he’s been following on his morning walks."
    },
    {
      "name": "Sam",
      "scenario": "Sam stays tucked under the duvet behind his drawn blackout curtains until late afternoon, completely unaware of the Saturday afternoon sun. As evening falls, he emerges to assemble a towering charcuterie board on the coffee table, carefully stepping around the familiar pile of laundry he’s left on the living room floor for days."
    }
  ]
}
